/// Enqueues a new [Message] which should be delivered to the remote peer.
void enqueueMessage(Message message) {
  ensureNotClosingSync(() {
    if (!wasTerminated) {
      _messages.addLast(message);
      _trySendMessages();
    }
  });
}
