/// Returns one slot to [pooled], closing the connection if it has gone idle.
void _freeSlot(_PooledConnection pooled) {
  pooled.inFlightCount--;
  if (_terminated) {
    _maybeCompleteDrain();
  } else {
    _closeIfIdle(pooled);
  }
}
